package com.leaveyouragent.leave.crypto

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The shared test vectors, in Kotlin.
 *
 * One file of vectors is the contract between the server, the iPhone app and the Android app:
 * vectors/v1.json, generated by Leave's server code. The iPhone's tests read the same file. Each
 * test here mirrors the one of the same name in ios/Tests/LeaveCryptoCoreTests/LeaveCryptoTests.swift.
 * Code that passes these seals what the server and an iPhone open, and opens what they seal.
 *
 * In this repository they run on a plain JVM (`./gradlew test` in android/), where the ciphers
 * come from Java. The app also runs the same tests on a phone, where they come from Android.
 */
abstract class LeaveCryptoVectors {
  /** The text of v1.json, from wherever this run can read it. */
  protected abstract fun vectorsText(): String

  private val core = LeaveCryptoCore
  private val vectors by lazy { JSONObject(vectorsText()) }

  private fun cases(group: String): List<JSONObject> = vectors.getJSONArray(group).objects()

  private fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }

  private fun JSONObject.bytes(name: String): ByteArray = core.fromBase64url(getString(name)) ?: error("$name is not base64url")

  private fun String.utf8(): ByteArray = toByteArray(Charsets.UTF_8)

  @Test
  fun recordAead() {
    val all = cases("recordAead")
    assertFalse(all.isEmpty())
    for (c in all) {
      val name = c.getString("name")
      val aad = c.getString("aad").utf8()
      assertArrayEquals(name, aad, core.aad(c.getString("recordType"), c.getString("recordId")))
      val wire = core.seal(c.bytes("dek"), c.bytes("plaintext"), aad, c.bytes("nonce"))
      assertEquals(name, c.getString("wire"), core.base64url(wire))
      assertArrayEquals(c.bytes("plaintext"), core.open(c.bytes("dek"), c.bytes("wire"), aad))
      assertThrows(Exception::class.java) { core.open(c.bytes("dek"), c.bytes("wire"), "leave:v1:other:x".utf8()) }
    }
  }

  @Test
  fun aSealWithNoNonceGivenDrawsItsOwnAndNeverTheSameTwice() {
    val key = ByteArray(32) { 7 }
    val first = core.seal(key, "x".utf8(), core.aad("strand", "a"))
    val second = core.seal(key, "x".utf8(), core.aad("strand", "a"))
    assertEquals(12 + 1 + 16, first.size)
    assertFalse(first.contentEquals(second))
    assertArrayEquals("x".utf8(), core.open(key, first, core.aad("strand", "a")))
  }

  @Test
  fun shareWrap() {
    for (c in cases("shareWrap")) {
      val name = c.getString("name")
      assertEquals(name, c.getString("wrapKey"), core.base64url(core.wrapKey(c.bytes("share"), c.getString("recordId"))))
      val wire = core.shareWrap(c.bytes("share"), c.getString("recordType"), c.getString("recordId"), c.bytes("dek"), c.bytes("nonce"))
      assertEquals(name, c.getString("wire"), core.base64url(wire))
      assertArrayEquals(c.bytes("dek"), core.shareUnwrap(c.bytes("share"), c.getString("recordType"), c.getString("recordId"), c.bytes("wire")))
    }
  }

  @Test
  fun accountKey() {
    for (c in cases("accountKey")) {
      val name = c.getString("name")
      // Every candidate the vector lists, the rejected ones too: the same bytes, the same verdict.
      for (candidate in c.getJSONArray("candidates").objects()) {
        val output = core.hkdf(c.bytes("share"), "leave:v1:account-key".utf8(), "${c.getString("accountId")}:${candidate.getInt("counter")}".utf8(), 32)
        assertEquals(name, candidate.getString("output"), core.base64url(output))
        assertEquals(name, candidate.getBoolean("accepted"), core.scalarInRange(output))
      }
      val scalar = core.accountScalar(c.bytes("share"), c.getString("accountId"))
      assertEquals(name, c.getString("privateScalar"), core.base64url(scalar))
      assertEquals(name, c.getString("publicKeyRaw"), core.base64url(core.publicKeyRaw(scalar)))
      assertEquals(name, c.getString("publicKeySpki"), core.base64url(core.accountPublicKeySpki(c.bytes("share"), c.getString("accountId"))))
      assertArrayEquals(c.bytes("publicKeyRaw"), core.rawOfSpki(c.bytes("publicKeySpki")))
    }
    assertFalse(core.scalarInRange(ByteArray(32)))
    assertFalse(core.scalarInRange(ByteArray(32) { 0xff.toByte() }))
    assertTrue(core.scalarInRange(ByteArray(31) + byteArrayOf(1)))
    // The curve's order itself is out; one less is in.
    val order = core.hex("ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551")
    assertFalse(core.scalarInRange(order))
    assertTrue(core.scalarInRange(order.copyOf(31) + byteArrayOf(0x50)))
  }

  @Test
  fun aPublicKeyThatIsNotAPointOnTheCurveIsRefused() {
    val spki = cases("accountKey").first().bytes("publicKeySpki")
    val offCurve = spki.copyOf().also { it[it.size - 1] = (it[it.size - 1] + 1).toByte() }
    assertThrows(LeaveCryptoCore.Failure::class.java) { core.rawOfSpki(offCurve) }
    assertThrows(LeaveCryptoCore.Failure::class.java) { core.rawOfSpki(spki.copyOf(spki.size - 1)) }
    assertThrows(LeaveCryptoCore.Failure::class.java) { core.hpkeSeal(offCurve, "leave:v1:x", ByteArray(32)) }
  }

  @Test
  fun hpke() {
    for (c in cases("hpke")) {
      val name = c.getString("name")
      val scalar = c.bytes("recipientScalar")
      val spki = c.bytes("recipientPublicKeySpki")
      assertEquals(name, c.getString("recipientPublicKeySpki"), core.base64url(core.spkiOfRaw(core.publicKeyRaw(scalar))))
      assertArrayEquals(name, c.bytes("plaintext"), core.hpkeOpen(scalar, c.getString("info"), c.bytes("wire")))
      // Unlike the iPhone's library, this one can be handed the sender's key, so the seal itself
      // is checked byte for byte as well as by opening it.
      assertEquals(name, c.getString("wire"), core.base64url(core.hpkeSeal(spki, c.getString("info"), c.bytes("plaintext"), c.bytes("ephemeralIkm"))))
      val mine = core.hpkeSeal(spki, c.getString("info"), c.bytes("plaintext"))
      assertEquals(65 + c.bytes("plaintext").size + 16, mine.size)
      assertFalse(name, mine.contentEquals(c.bytes("wire")))
      assertArrayEquals(c.bytes("plaintext"), core.hpkeOpen(scalar, c.getString("info"), mine))
      assertThrows(Exception::class.java) { core.hpkeOpen(scalar, "leave:v1:xwrap:other", mine) }
    }
  }

  /** The open this phone's own agreement key uses: the key only answers "what do we agree on?". */
  @Test
  fun hpkeOpensWhenTheRecipientsKeyOnlyAnswersWhatTheTwoAgreeOn() {
    for (c in cases("hpke")) {
      val name = c.getString("name")
      val scalar = c.bytes("recipientScalar")
      val own = core.publicKeyRaw(scalar)
      var asked = 0
      val agree = { sender: ByteArray -> asked += 1; core.agreement(scalar, sender) }
      assertArrayEquals(name, c.bytes("plaintext"), core.hpkeOpenWith(agree, own, c.getString("info"), c.bytes("wire")))
      assertEquals("the key is asked once", 1, asked)
      val mine = core.hpkeSeal(c.bytes("recipientPublicKeySpki"), c.getString("info"), c.bytes("plaintext"))
      assertArrayEquals(core.hpkeOpen(scalar, c.getString("info"), mine), core.hpkeOpenWith(agree, own, c.getString("info"), mine))
      assertThrows(Exception::class.java) { core.hpkeOpenWith(agree, own, "leave:v1:xwrap:other", mine) }
      // A sender's key that is not a point on the curve is refused before the key is asked anything.
      asked = 0
      val offCurve = mine.copyOf().also { it[64] = (it[64] + 1).toByte() }
      assertThrows(LeaveCryptoCore.Failure::class.java) { core.hpkeOpenWith(agree, own, c.getString("info"), offCurve) }
      assertEquals(0, asked)
    }
  }

  @Test
  fun grant() {
    val c = cases("grant").first()
    val pkcs8 = c.bytes("rsaPrivateKeyPkcs8")
    val spki = c.bytes("rsaPublicKeySpki")
    val sessionKey = c.bytes("sessionKey")
    // The vector's own seal opens to the session key; ours opens the same way (OAEP is randomised).
    assertArrayEquals(sessionKey, core.rsaOpen(pkcs8, c.bytes("sealedSessionKey")))
    val mine = core.rsaSeal(spki, sessionKey)
    assertEquals(384, mine.size)
    assertArrayEquals(sessionKey, core.rsaOpen(pkcs8, mine))
    for (r in c.getJSONArray("records").objects()) {
      val aad = core.grantAad(c.getString("sessionId"), r.getString("id"))
      assertArrayEquals(r.getString("aad").utf8(), aad)
      val sealed = core.sealDek(sessionKey, c.getString("sessionId"), r.getString("id"), r.bytes("dek"), r.bytes("nonce"))
      assertEquals(r.getString("sealedDek"), core.base64url(sealed))
    }
  }

  @Test
  fun signatures() {
    for (c in cases("signatures")) {
      val name = c.getString("name")
      val spki = c.bytes("publicKeySpki")
      val message = c.bytes("message")
      assertTrue(name, core.verify(spki, message, c.bytes("signatureRaw")))
      assertTrue(name, core.verify(spki, message, c.bytes("signatureDer")))
      assertFalse(name, core.verify(spki, message + byteArrayOf(0), c.bytes("signatureRaw")))
      // The vector's two signatures are two signings, not one written two ways. Each still
      // verifies when rewritten in the other form, and the rewriting undoes itself.
      assertTrue(name, core.verify(spki, message, core.derOfRaw(c.bytes("signatureRaw"))))
      assertTrue(name, core.verify(spki, message, core.rawOfDer(c.bytes("signatureDer"))))
      assertArrayEquals(name, c.bytes("signatureRaw"), core.rawOfDer(core.derOfRaw(c.bytes("signatureRaw"))))
      assertArrayEquals(name, c.bytes("signatureDer"), core.derOfRaw(core.rawOfDer(c.bytes("signatureDer"))))
    }
  }

  @Test
  fun theAccountKeySignsWhatItsPublicHalfVerifies() {
    for (c in cases("accountKey")) {
      val scalar = c.bytes("privateScalar")
      val message = "01J8Z3V4Q6X7R2M9K5T0W1Y8DV${c.getString("accountId")}".utf8()
      val signature = core.sign(scalar, message)
      assertEquals(64, signature.size)
      assertTrue(core.verify(c.bytes("publicKeySpki"), message, signature))
      assertFalse(core.verify(c.bytes("publicKeySpki"), message + byteArrayOf(0), signature))
    }
  }

  /** Argon2id 64 MiB, 3 passes, 1 lane, then AES-256-GCM over the share with no associated data. */
  @Test
  fun recoveryBlob() {
    for (c in cases("recovery")) {
      val name = c.getString("name")
      val argon = c.getJSONObject("argon2id")
      assertEquals(64 * 1024, argon.getInt("memoryKiB"))
      assertEquals(3, argon.getInt("iterations"))
      assertEquals(1, argon.getInt("parallelism"))
      assertEquals(32, argon.getInt("outputBytes"))
      val code = c.getString("recoveryCode")
      assertEquals(name, c.getString("key"), core.base64url(core.recoveryKey(code, c.bytes("salt"))))
      assertEquals(name, c.getString("blob"), core.base64url(core.sealRecovery(c.bytes("share"), code, c.bytes("salt"), c.bytes("nonce"))))
      assertArrayEquals(c.bytes("share"), core.openRecovery(c.bytes("blob"), code))
      val wrong = (if (code[0] == '0') "1" else "0") + code.drop(1)
      assertThrows(Exception::class.java) { core.openRecovery(c.bytes("blob"), wrong) }
      assertThrows(LeaveCryptoCore.Failure::class.java) { core.openRecovery(c.bytes("blob").copyOf(76), code) }
    }
  }

  @Test
  fun recoveryCodeShape() {
    val code = core.newRecoveryCode()
    assertEquals(28, code.length)
    assertTrue(code.all { it in LeaveCryptoCore.RECOVERY_ALPHABET })
    assertFalse(code == core.newRecoveryCode())
    val grouped = core.groupedRecoveryCode(code)
    assertEquals(28 + 6, grouped.length)
    assertEquals(code, core.normalizeRecoveryCode(grouped))
    assertEquals(code, core.normalizeRecoveryCode(grouped.lowercase().replace(' ', '-')))
    assertEquals("0".repeat(26) + "11", core.normalizeRecoveryCode("O".repeat(26) + "IL"))
    assertNull(core.normalizeRecoveryCode(code.dropLast(1)))
    assertNull(core.normalizeRecoveryCode("U" + code.drop(1)))
  }

  @Test
  fun compareCode() {
    // Six digits, the same for the same two inputs, and different when either changes.
    val a = core.compareCode("key-one", "01J8Z3V4Q6X7R2M9K5T0W1Y8RQ")
    assertTrue(Regex("^[0-9]{6}$").matches(a))
    assertEquals(a, core.compareCode("key-one", "01J8Z3V4Q6X7R2M9K5T0W1Y8RQ"))
    assertFalse(a == core.compareCode("key-two", "01J8Z3V4Q6X7R2M9K5T0W1Y8RQ"))
    // Worked by hand from the definition, so a change to it is seen.
    val digest = core.sha256("leave:v1:device-compare:01J8Z3V4Q6X7R2M9K5T0W1Y8RQ:key-one".utf8())
    val number = digest.take(4).fold(0L) { acc, b -> acc * 256 + (b.toLong() and 0xff) }
    assertEquals("%06d".format(number % 1_000_000), a)
  }

  // Samples from the server's own code (2026-09-29), with fixed, made-up keys, as in the iPhone's tests.

  private val dek11 = ByteArray(32) { 0x11 }

  @Test
  fun serverSampleShareWrap() {
    val share = ByteArray(32) { 0x07 }
    assertEquals("BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc", core.base64url(share))
    assertEquals("1KCpaAu0sNEXu9aO6_oP0_hOXp6UOhls9CqPR_lAfuM", core.base64url(core.wrapKey(share, "01J8Z3V4Q6X7R2M9K5T0W1Y8NE")))
    val wire = core.shareWrap(share, "contract", "01J8Z3V4Q6X7R2M9K5T0W1Y8NE", dek11, ByteArray(12) { 0x55 })
    assertEquals("VVVVVVVVVVVVVVVVf3-Gg294UwPHNj9unms0aGqwjee1oGS1nNBSg4Smll37k1DAmKj7Oyb7xJAO83W2", core.base64url(wire))
  }

  @Test
  fun serverSampleGrantDek() {
    val sealed = core.sealDek(ByteArray(32) { 0x22 }, "01J8Z3V4Q6X7R2M9K5T0W1Y8SS", "01J8Z3V4Q6X7R2M9K5T0W1Y8NE", dek11, ByteArray(12) { 0x33 })
    assertEquals("MzMzMzMzMzMzMzMzZ9LX-2Q9Z3kZ_IphBMAcgzSwepZJoXjgG8Y554-eE2yNmsXUbD9cewrhEa1uUNCk", core.base64url(sealed))
  }

  @Test
  fun serverSampleUploadCiphertext() {
    val wire = core.seal(dek11, "%PDF-1.7 sample".utf8(), core.aad("contract", "01J8Z3V4Q6X7R2M9K5T0W1Y8NE"), ByteArray(12) { 0x66 })
    assertEquals("ZmZmZmZmZmZmZmZmnb3Hp9ckv43jepR-HfTtJDMmcdX2Sc5n7g8z4zUJtQ", core.base64url(wire))
    assertEquals(43, wire.size)
    assertEquals("ae2a2e0cb1e983358a5ec961be216b8bf89542098eb24b33f913c6c8050461df", core.sha256Hex(wire))
  }

  @Test
  fun encoding() {
    assertEquals("-_8", core.base64url(byteArrayOf(0xfb.toByte(), 0xff.toByte())))
    assertArrayEquals(byteArrayOf(0xfb.toByte(), 0xff.toByte()), core.fromBase64url("-_8"))
    assertArrayEquals(byteArrayOf(0xfb.toByte(), 0xff.toByte()), core.fromBase64url("-_8="))
    assertNull(core.fromBase64url("not base64!"))
    assertEquals("\"01J8\"", core.jsonString("01J8"))
    assertEquals("\"a\\\"b\\\\c\\u000a\"", core.jsonString("a\"b\\c\n"))
  }
}
